(r, big) => {
    const R = big ? 500 : r.int(1, 5), C = big ? 500 : r.int(1, 5), tries = big ? 150000 : r.int(0, 8);
    const g = Array.from({ length: R }, () => new Array(C).fill("."));
    const free = (y, x) => y < 0 || y >= R || x < 0 || x >= C || g[y][x] === ".";
    for (let t = 0; t < tries; t++) {
      const horiz = r.bool(), len = r.int(1, big ? 6 : 3);
      const y = r.int(0, R - 1), x = r.int(0, C - 1);
      const cells = [];
      for (let k = 0; k < len; k++) cells.push(horiz ? [y, x + k] : [y + k, x]);
      if (cells.some(([a, b]) => a >= R || b >= C)) continue;
      if (!cells.every(([a, b]) => free(a, b) && free(a - 1, b) && free(a + 1, b) && free(a, b - 1) && free(a, b + 1))) continue;
      for (const [a, b] of cells) g[a][b] = "X";
    }
    return [g];
  }

