class Solution:
    def countShips(self, grid: List[List[str]]) -> int:
        R, C = len(grid), len(grid[0])
        seen = [[False] * C for _ in range(R)]
        count = 0
        for r in range(R):
            for c in range(C):
                if grid[r][c] != "X" or seen[r][c]:
                    continue
                count += 1
                seen[r][c] = True
                stack = [(r, c)]
                while stack:
                    y, x = stack.pop()
                    for ny, nx in ((y + 1, x), (y - 1, x), (y, x + 1), (y, x - 1)):
                        if 0 <= ny < R and 0 <= nx < C and grid[ny][nx] == "X" and not seen[ny][nx]:
                            seen[ny][nx] = True
                            stack.append((ny, nx))
        return count

