function countShips(grid: string[][]): number {
  let count = 0;
  for (let r = 0; r < grid.length; r++) {
    for (let c = 0; c < grid[0].length; c++) {
      if (grid[r][c] !== "X") continue;
      if (r > 0 && grid[r - 1][c] === "X") continue;
      if (c > 0 && grid[r][c - 1] === "X") continue;
      count++;
    }
  }
  return count;
}

